import { chromium } from 'playwright';
const browser = await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true,args:['--no-sandbox']});
const page=await browser.newPage({viewport:{width:1440,height:1000},deviceScaleFactor:1});
page.on('pageerror',console.error);
await page.goto('http://127.0.0.1:5173');
await page.waitForTimeout(1600);
await page.screenshot({path:'.desktop-test.png'});
await page.click('[data-face="R"]');
await page.waitForTimeout(600);
console.log('After R:',await page.locator('#status-text').textContent(),await page.locator('#move-count').textContent());
await page.click('#undo');
await page.waitForTimeout(600);
console.log('After undo:',await page.locator('#status-text').textContent());
await page.click('#scramble');
await page.waitForTimeout(4200);
console.log('After scramble:',await page.locator('#status-text').textContent());
await page.click('#solve');
await page.waitForTimeout(4200);
console.log('After solve:',await page.locator('#status-text').textContent());
await page.setViewportSize({width:390,height:844});
await page.waitForTimeout(500);
await page.screenshot({path:'.mobile-test.png',fullPage:true});
console.log('Mobile horizontal overflow:',await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth));
await browser.close();
